# Terraform: Refactor Dev/Prod Blocks to `for_each` Module

## Architecture

Replace separate resource blocks per environment with **one reusable module invoked via `for_each`**, then migrate state without recreation.

---

## Step 1: Create the Module Structure

```
terraform/
├── modules/
│   └── app_environment/
│       ├── main.tf
│       ├── variables.tf
│       ├── outputs.tf
│       └── README.md
├── main.tf
├── variables.tf
├── dev.tfvars
└── prod.tfvars
```

### `modules/app_environment/variables.tf`

```hcl
variable "environment" {
  description = "Environment name (dev/prod)"
  type        = string
}

variable "region" {
  description = "AWS region"
  type        = string
}

variable "eks_node_count" {
  type = number
}

variable "eks_instance_type" {
  type = string
}

variable "rds_instance_class" {
  type = string
}

variable "rds_multi_az" {
  type = bool
}

variable "s3_enable_replication" {
  type = bool
}

variable "s3_replica_region" {
  type    = string
  default = null
}

variable "iam_use_oidc" {
  type = bool
}

variable "https_provider" {
  description = "alb or cloudfront"
  type        = string
}

variable "kms_key_id" {
  type    = string
  default = null
}
```

### `modules/app_environment/main.tf`

```hcl
resource "aws_eks_cluster" "main" {
  name            = "${var.environment}-cluster"
  role_arn        = aws_iam_role.eks_cluster.arn
  version         = "1.29"

  vpc_config {
    subnet_ids = var.private_subnet_ids
  }
}

resource "aws_eks_node_group" "main" {
  cluster_name    = aws_eks_cluster.main.name
  node_group_name = "${var.environment}-nodes"
  node_role_arn   = aws_iam_role.eks_node.arn
  subnet_ids      = var.private_subnet_ids

  scaling_config {
    desired_size = var.eks_node_count
    max_size     = var.eks_node_count + 1
    min_size     = var.eks_node_count
  }

  instance_types = [var.eks_instance_type]
}

resource "aws_s3_bucket" "app_assets" {
  bucket = "${var.environment}-app-assets-${data.aws_caller_identity.current.account_id}"
}

resource "aws_s3_bucket_versioning" "app_assets" {
  bucket = aws_s3_bucket.app_assets.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "app_assets" {
  bucket = aws_s3_bucket.app_assets.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.kms_key_id != null ? "aws:kms" : "AES256"
      kms_master_key_id = var.kms_key_id
    }
  }
}

resource "aws_s3_bucket_public_access_block" "app_assets" {
  bucket = aws_s3_bucket.app_assets.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Cross-region replication (prod only)
resource "aws_s3_bucket_replication_configuration" "app_assets" {
  count  = var.s3_enable_replication ? 1 : 0
  bucket = aws_s3_bucket.app_assets.id
  role   = aws_iam_role.s3_replication[0].arn

  rule {
    status   = "Enabled"
    priority = 1

    destination {
      bucket       = "arn:aws:s3:::${var.environment}-app-assets-replica-${data.aws_caller_identity.current.account_id}"
      replication_time {
        status = "Enabled"
        time {
          minutes = 15
        }
      }
    }
  }

  depends_on = [aws_s3_bucket_versioning.app_assets]
}

resource "aws_db_instance" "postgres" {
  identifier              = "${var.environment}-postgres"
  engine                  = "postgres"
  engine_version          = "15.3"
  instance_class          = var.rds_instance_class
  allocated_storage       = 20
  storage_encrypted       = true
  kms_key_id              = var.kms_key_id
  multi_az                = var.rds_multi_az
  publicly_accessible     = false
  skip_final_snapshot     = var.environment == "dev"
  deletion_protection     = var.environment == "prod"
  backup_retention_period = var.environment == "prod" ? 30 : 7
  backup_window           = "03:00-04:00"
  maintenance_window      = "sun:04:00-sun:05:00"

  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.rds.id]

  db_name  = "appdb"
  username = "postgres"
  password = random_password.db_password.result
}

resource "random_password" "db_password" {
  length  = 32
  special = true
}

resource "aws_secretsmanager_secret" "db_connection" {
  name                    = "${var.environment}/db-connection-string"
  recovery_window_in_days = var.environment == "prod" ? 30 : 7
}

resource "aws_secretsmanager_secret_version" "db_connection" {
  secret_id = aws_secretsmanager_secret.db_connection.id
  secret_string = jsonencode({
    host     = aws_db_instance.postgres.endpoint
    port     = 5432
    database = aws_db_instance.postgres.db_name
    username = aws_db_instance.postgres.username
    password = random_password.db_password.result
  })
}

resource "aws_iam_user" "service_account" {
  name = "${var.environment}-service-account"
}

resource "aws_iam_role" "service_account" {
  name = "${var.environment}-service-account-role"

  assume_role_policy = var.iam_use_oidc ? data.aws_iam_policy_document.oidc_trust.json : data.aws_iam_policy_document.user_trust.json
}

data "aws_iam_policy_document" "user_trust" {
  statement {
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = [aws_iam_user.service_account.arn]
    }
    actions = ["sts:AssumeRole"]
  }
}

data "aws_iam_policy_document" "oidc_trust" {
  statement {
    effect = "Allow"
    principals {
      type        = "Federated"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:oidc-provider/${aws_eks_cluster.main.identity[0].oidc[0].issuer}"]
    }
    actions = ["sts:AssumeRoleWithWebIdentity"]
    condition {
      test     = "StringEquals"
      variable = "${aws_eks_cluster.main.identity[0].oidc[0].issuer}:sub"
      values   = ["system:serviceaccount:default:app"]
    }
  }
}

resource "aws_iam_role_policy" "service_account" {
  name   = "${var.environment}-service-account-policy"
  role   = aws_iam_role.service_account.id
  policy = data.aws_iam_policy_document.service_account_policy.json
}

data "aws_iam_policy_document" "service_account_policy" {
  statement {
    actions = [
      "s3:GetObject",
      "s3:ListBucket"
    ]
    resources = [
      aws_s3_bucket.app_assets.arn,
      "${aws_s3_bucket.app_assets.arn}/*"
    ]
  }

  statement {
    actions = [
      "secretsmanager:GetSecretValue"
    ]
    resources = [
      aws_secretsmanager_secret.db_connection.arn
    ]
  }

  # Prod: deny wildcard actions
  dynamic "statement" {
    for_each = var.environment == "prod" ? [1] : []
    content {
      effect  = "Deny"
      actions = ["*"]
      resources = ["*"]
      condition {
        test     = "StringLike"
        variable = "aws:PrincipalArn"
        values   = [aws_iam_role.service_account.arn]
      }
    }
  }
}

# ALB or CloudFront branch
resource "aws_lb" "app" {
  count              = var.https_provider == "alb" ? 1 : 0
  name               = "${var.environment}-alb"
  internal           = var.environment == "dev"
  load_balancer_type = "application"
  subnets            = var.public_subnet_ids

  enable_deletion_protection = var.environment == "prod"
}

resource "aws_lb_listener" "app_https" {
  count             = var.https_provider == "alb" ? 1 : 0
  load_balancer_arn = aws_lb.app[0].arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS-1-2-2017-01"
  certificate_arn   = aws_acm_certificate.app[0].arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.app[0].arn
  }
}

resource "aws_cloudfront_distribution" "app" {
  count   = var.https_provider == "cloudfront" ? 1 : 0
  enabled = true

  origin {
    domain_name = aws_lb.app[0].dns_name
    origin_id   = "alb"

    custom_origin_config {
      http_port              = 80
      https_port             = 443
      origin_protocol_policy = "https-only"
      origin_ssl_protocols   = ["TLSv1.2"]
    }
  }

  default_cache_behavior {
    allowed_methods  = ["GET", "HEAD"]
    cached_methods   = ["GET", "HEAD"]
    target_origin_id = "alb"

    forwarded_values {
      query_string = false
      cookies {
        forward = "none"
      }
    }

    viewer_protocol_policy = "redirect-to-https"
  }

  viewer_certificate {
    cloudfront_default_certificate = true
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }
}

data "aws_caller_identity" "current" {}
```

### `modules/app_environment/outputs.tf`

```hcl
output "eks_cluster_name" {
  value = aws_eks_cluster.main.name
}

output "s3_bucket" {
  value = aws_s3_bucket.app_assets.id
}

output "rds_endpoint" {
  value = aws_db_instance.postgres.endpoint
}

output "service_account_role_arn" {
  value = aws_iam_role.service_account.arn
}

output "alb_dns_name" {
  value = try(aws_lb.app[0].dns_name, null)
}

output "cloudfront_domain_name" {
  value = try(aws_cloudfront_distribution.app[0].domain_name, null)
}
```

---

## Step 2: Refactor Main Configuration

### `main.tf`

```hcl
locals {
  environments = {
    dev = {
      region               = "us-east-1"
      eks_node_count       = 2
      eks_instance_type    = "t3.medium"
      rds_instance_class   = "db.t3.micro"
      rds_multi_az         = false
      s3_enable_replication = false
      iam_use_oidc         = false
      https_provider       = "alb"
      kms_key_id           = null
    }
    prod = {
      region               = "us-east-1"
      eks_node_count       = 4
      eks_instance_type    = "t3.large"
      rds_instance_class   = "db.t3.medium"
      rds_multi_az         = true
      s3_enable_replication = true
      s3_replica_region    = "us-west-2"
      iam_use_oidc         = true
      https_provider       = "cloudfront"
      kms_key_id           = aws_kms_key.prod.id
    }
  }
}

# Prod-only KMS key for encryption
resource "aws_kms_key" "prod" {
  description             = "Prod environment encryption key"
  deletion_window_in_days = 10
  enable_key_rotation     = true

  tags = {
    Environment = "prod"
  }
}

module "app_environment" {
  for_each = local.environments

  source = "./modules/app_environment"

  environment           = each.key
  region                = each.value.region
  eks_node_count        = each.value.eks_node_count
  eks_instance_type     = each.value.eks_instance_type
  rds_instance_class    = each.value.rds_instance_class
  rds_multi_az          = each.value.rds_multi_az
  s3_enable_replication = each.value.s3_enable_replication
  s3_replica_region     = try(each.value.s3_replica_region, null)
  iam_use_oidc          = each.value.iam_use_oidc
  https_provider        = each.value.https_provider
  kms_key_id            = try(each.value.kms_key_id, null)

  providers = {
    aws = aws.primary
  }
}

provider "aws" {
  alias  = "primary"
  region = "us-east-1"
}
```

### `dev.tfvars` & `prod.tfvars`

These are now optional (config is in `locals`), or simplified:

```hcl
